<script setup lang="ts">
import { ui } from "../ui"
import AssigneeFilter from './AssigneeFilter.vue'
import { bootstrap } from '../composables/api'
import { reactive, watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
defineProps<{environments?:string[];advanced?:boolean;allowedTags?:string[];hideTestToggle?:boolean}>()
const route=useRoute(),router=useRouter()
const draft=reactive<Record<string,string>>({})
watch(()=>route.query,()=>{for(const k of Object.keys(draft))delete draft[k];for(const[k,v]of Object.entries(route.query))if(typeof v==='string')draft[k]=v;draft.status??='unresolved';draft.sort??='last_seen';draft.per_page??='25'},{immediate:true})
function set(key:string,value:string){router.replace({query:{...route.query,[key]:value||undefined,page:undefined}})}
function search(){router.replace({query:{...draft,page:undefined}})}
</script>
<template><div v-if="!advanced" :class="ui('$all', '$div', 'investigation-controls')"><label :class="ui('$all', '$label')"><span :class="ui('$all', '$span', 'sr-only')">Environment</span><select :class="ui('$all', '$select')" aria-label="Environment" :value="route.query.environment??''" @change="set('environment',($event.target as HTMLSelectElement).value)"><option :class="ui('$all', '$option')" value="">All environments</option><option :class="ui('$all', '$option')" v-for="e in environments" :key="e">{{ e }}</option></select></label><label :class="ui('$all', '$label')"><span :class="ui('$all', '$span', 'sr-only')">Time range</span><select :class="ui('$all', '$select')" aria-label="Time range" :value="route.query.range??'24h'" @change="set('range',($event.target as HTMLSelectElement).value)"><option :class="ui('$all', '$option')" value="1h">Last hour</option><option :class="ui('$all', '$option')" value="24h">Last 24 hours</option><option :class="ui('$all', '$option')" value="7d">Last 7 days</option><option :class="ui('$all', '$option')" value="30d">Last 30 days</option></select></label><label v-if="!hideTestToggle" :class="ui('$all', '$label', 'test-toggle')"><input :class="ui('$all', '$input')" type="checkbox" :checked="route.query.include_tests==='1'" @change="set('include_tests',($event.target as HTMLInputElement).checked?'1':'0')">Include test events</label></div><form v-if="advanced" :class="ui('$all', '$form', 'inbox-filters')" @submit.prevent="search"><label :class="ui('$all', '$label', 'search-field')"><span :class="ui('$all', '$span', 'sr-only')">Search exception class or message</span><input :class="ui('$all', '$input')" v-model="draft.search" aria-describedby="inbox-search-history" placeholder="Search exception class or message" type="search"></label><select :class="ui('$all', '$select')" v-model="draft.status" aria-label="Status"><option :class="ui('$all', '$option')" value="unresolved">Unresolved</option><option :class="ui('$all', '$option')" value="resolved">Resolved</option><option :class="ui('$all', '$option')" value="ignored">Ignored</option><option :class="ui('$all', '$option')" value="snoozed">Snoozed</option><option :class="ui('$all', '$option')" value="all">All statuses</option></select><select :class="ui('$all', '$select')" v-model="draft.sort" aria-label="Sort errors"><option :class="ui('$all', '$option')" value="last_seen">Last seen</option><option :class="ui('$all', '$option')" value="first_seen">First seen</option><option :class="ui('$all', '$option')" value="occurrences">Occurrences in range</option></select><button :class="ui('$all', '$button', 'button')" type="submit">Apply filters</button><p id="inbox-search-history" :class="ui('$all', '$p', 'search-disclosure')">Search terms appear in authenticated URLs and browser history.</p><details :class="ui('$all', '$details', 'advanced-filters')"><summary :class="ui('$all', '$summary')">More filters</summary><div :class="ui('$all', '$div', 'filter-grid')"><label :class="ui('$all', '$label', 'field')">Origin<select :class="ui('$all', '$select')" v-model="draft.origin"><option :class="ui('$all', '$option')" value="">Any origin</option><option :class="ui('$all', '$option')" v-for="o in ['web','job','command','unknown']" :key="o">{{o}}</option></select></label><AssigneeFilter :class="ui('$all', '$AssigneeFilter')" v-if="bootstrap?.features.assignments" v-model="draft.assignee"/><label :class="ui('$all', '$label', 'field')">Exact exception class<input :class="ui('$all', '$input')" v-model="draft.class"></label><label v-if="allowedTags?.length" :class="ui('$all', '$label', 'field')">Permitted tag (key:value)<input :class="ui('$all', '$input')" v-model="draft.tag"><small :class="ui('$all', '$small')">{{ allowedTags.join(', ') }}</small></label><label v-for="field in ['first_after','first_before','last_after','last_before']" :key="field" :class="ui('$all', '$label', 'field')">{{ field.replace('_',' seen ') }} (UTC)<input :class="ui('$all', '$input')" v-model="draft[field]" type="date"></label><label :class="ui('$all', '$label', 'field')">Rows per page<select :class="ui('$all', '$select')" v-model="draft.per_page"><option :class="ui('$all', '$option')" v-for="size in [25,50,100]" :key="size">{{size}}</option></select></label></div></details></form></template>
